"use client";

import { useRef, type ReactNode } from "react";
import { useGSAP } from "@gsap/react";
import { gsap, EASE, DURATION, TRIGGER_START } from "@/shared/lib/animations/gsap-config";
import { useReducedMotion } from "@/shared/lib/animations/use-reduced-motion";

interface RevealOnScrollProps {
  children: ReactNode;
  className?: string;
  y?: number;          // px to travel from, default 40
  x?: number;          // px to travel horizontally, optional
  delay?: number;
  duration?: number;
  start?: string;      // ScrollTrigger start position
  as?: "div" | "section" | "article" | "span" | "p";
}

export function RevealOnScroll({
  children,
  className,
  y = 40,
  x,
  delay = 0,
  duration = DURATION.base,
  start = TRIGGER_START,
  as: Tag = "div",
}: RevealOnScrollProps) {
  const ref = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0, x: 0 });
        return;
      }

      const fromVars: any = { opacity: 0, duration, delay, ease: EASE.smooth };
      if (x !== undefined) {
        fromVars.x = x;
      } else {
        fromVars.y = y;
      }

      gsap.from(ref.current, {
        ...fromVars,
        scrollTrigger: {
          trigger: ref.current,
          start,
          toggleActions: "play none none reverse",
        },
      });
    },
    { scope: ref, dependencies: [reduced, y, x, delay, duration, start] }
  );

  const Comp = Tag as any;
  return (
    <Comp ref={ref} className={className}>
      {children}
    </Comp>
  );
}

"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import { gsap, EASE } from "@/shared/lib/animations/gsap-config";
import { useReducedMotion } from "@/shared/lib/animations/use-reduced-motion";

interface TextRevealProps {
  text: string;
  className?: string;
  as?: "h1" | "h2" | "h3" | "p";
  delay?: number;
}

export function TextReveal({ text, className, as: Tag = "h2", delay = 0 }: TextRevealProps) {
  const ref = useRef<HTMLElement>(null);
  const reduced = useReducedMotion();
  const words = text.split(" ");

  useGSAP(
    () => {
      const spans = ref.current?.querySelectorAll<HTMLElement>(".word-inner");
      if (!spans?.length) return;

      if (reduced) {
        gsap.set(spans, { yPercent: 0, opacity: 1 });
        return;
      }

      gsap.from(spans, {
        yPercent: 100,
        opacity: 0,
        duration: 0.9,
        delay,
        ease: EASE.snappy,
        stagger: 0.045,
        scrollTrigger: {
          trigger: ref.current,
          start: "top 85%",
          toggleActions: "play none none reverse",
        },
      });
    },
    { scope: ref, dependencies: [reduced, delay] }
  );

  const Comp = Tag as any;
  return (
    <Comp ref={ref} className={className}>
      {words.map((word, i) => (
        <span key={i} className="inline-block overflow-hidden pb-[0.08em] mr-[0.25em]">
          <span className="word-inner inline-block">{word}</span>
        </span>
      ))}
    </Comp>
  );
}

